            .verify_fact(&fact.clone().into(), VerifyState::new(crate::execute::execute_fact_stmt::VerifyStateLevel::BuiltinRule))
            .unwrap();
        assert_eq!(before, store_sizes(&rt));
        let VerifyFactResult::Equality(result) = result else {
